dot"></span> <small class="text-muted">updates automatically</small></span></div><div class="card-body" id="liveVisitors">@forelse($live as $s)<div class="d-flex justify-content-between border-bottom pb-2 mb-2"><div><strong>{{ $s->presentation?->client?->company_name }}</strong><div class="stat-mini">Viewing {{ ucwords(str_replace('_',' ',$s->current_section?:'presentation')) }}</div></div><small class="text-muted">{{ $s->last_activity_at?->diffForHumans() }}</small></div>@empty<div class="empty-state py-4">No client is active right now.</div>@endforelse</div></div></div><div class="col-12"><div class="card"><div class="card-header"><strong>Recent client activity</strong></div><div class="card-body"><div class="timeline">@forelse($events as $e)<div class="timeline-item"><div class="timeline-time">{{ $e->occurred_at?->format('d M Y, h:i:s A') }}</div><div class="timeline-title">{{ $e->presentation?->client?->company_name }} · {{ ucwords(str_replace('_',' ',$e->event_type)) }}</div><div class="stat-mini">{{ $e->section_key?ucwords(str_replace('_',' ',$e->section_key)):'' }} {{ $e->element_key?'· '.$e->element_key:'' }}</div></div>@empty<div class="text-muted">No activity yet.</div>@endforelse</div></div></div></div></div>@endsection @push('scripts')<script>const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[c]));setInterval(async()=>{try{const r=await fetch('{{ route('admin.live') }}',{headers:{'Accept':'application/json'}});const a=await r.json();document.getElementById('liveVisitors').innerHTML=a.length?a.map(x=>`<div class="d-flex justify-content-between border-bottom pb-2 mb-2"><div><strong>${esc(x.client||'Client')}</strong><div class="stat-mini">Viewing ${esc((x.section||'presentation').replaceAll('_',' '))}</div></div><small class="text-muted">${esc(x.last_activity)}</small></div>`).join(''):'<div class="empty-state py-4">No client is active right now.</div>';}catch(e){}},15000);</script>@endpush